    subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-i", path, "-ar", "16000", "-ac", "1", out], check=True)
    return out

def words(t):
    return re.findall(r"[a-z0-9']+", t.lower().replace("-", " "))

def wer(ref, hyp):
    r, h = words(ref), words(hyp)
    d = np.arange(len(h) + 1)
    for i in range(1, len(r) + 1):
        prev, d[0] = d.copy(), i
        for j in range(1, len(h) + 1):
            d[j] = min(prev[j] + 1, d[j - 1] + 1, prev[j - 1] + (r[i - 1] != h[j - 1]))
    return d[-1] / len(r)

def pitch_stats(path):
    raw = subprocess.run(["ffmpeg", "-loglevel", "error", "-i", path, "-f", "f32le", "-ac", "1", "-ar", "16000", "-"], capture_output=True).stdout
    x = np.frombuffer(raw, dtype=np.float32)
    f0 = []
    for s in range(0, len(x) - 1024, 160):
        frame = x[s:s + 1024] * np.hanning(1024)
        if np.sqrt((frame ** 2).mean()) < 0.02:
            continue
        ac = np.correlate(frame, frame, "full")[1023:]
        lo, hi = 16000 // 400, 16000 // 70
        lag = lo + np.argmax(ac[lo:hi])
        if ac[lag] > 0.3 * ac[0]:
            f0.append(16000 / lag)
    f0 = np.array(f0)
    semis = 12 * np.log2(f0 / np.median(f0))
    return {"median_hz": round(float(np.median(f0)), 1), "pitch_range_semitones_p10_p90": round(float(np.percentile(semis, 90) - np.percentile(semis, 10)), 2)}

for label, path in [(a, b) for a, b in zip(sys.argv[1::2], sys.argv[2::2])]:
    w = wav16(path)
    hyp = subprocess.run(["whisper-cli", "-m", MODEL, "-f", w, "-nt", "-np"], capture_output=True, text=True).stdout.strip()
    dur = float(subprocess.run(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", path], capture_output=True, text=True).stdout)
    print(json.dumps({"take": label, "seconds": round(dur, 1), "wpm": round(len(words(REF)) / dur * 60), "wer": round(wer(REF, hyp), 3), **pitch_stats(path), "heard": hyp[:220]}, indent=1))
