import { EMPTY_QUERY, queryKey, useMatches, useViews, type SearchQuery } from "./views";

/**
 * What needs the person, worked out from what Kopi already knows rather than from a feed:
 * bid deadlines coming up, the next step Kopi set on each bid, bids nobody started, and
 * notices published this week that match the company or a saved view. Only read and done
